        xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
        print(f"bbox {min(xs)}-{max(xs)} x {min(ys)}-{max(ys)} cent {sum(xs)/len(xs):.1f},{sum(ys)/len(ys):.1f}")
    else:
        print("none")
