{"command":"python3 - << 'PY'
import workcell
from PIL import Image
import os

def find_features(path):
    im = Image.open(path)
    px = im.load(); w,h=im.size
    # pin tip: dark blob near bottom of gripper, typically y around 400-470, small
    # bore: dark circle on gray table
    dark=[]
    for y in range(h):
        for x in range(w):
            r,g,b=px[x,y]
            if r<50 and g<50 and b<55:
                dark.append((x,y))
    return w,h,len(dark)

# sweep
for z in (55, 48, 42):
    for y in (250, 255, 258, 262):
        mv = workcell.call("robot","move","397.27",str(y),str(z))
        if not mv.ok:
            print("MOVE FAIL", y, z, mv.text)
            continue
        cap = workcell.call("robot","camera","wrist")
        path = cap.text.split()[-1]
        print(z, y, path, "dark", find_features(path)[2])
print(workcell.call("robot","status").text)
